<?php
namespace Tests\Feature;use App\Domain\ApiHub\{ApiIdempotencyService,ApiWebhookDeliveryService};use App\Domain\ApiHub\Models\{TenantApiClient,TenantApiIdempotencyRecord,TenantApiKey,TenantApiQuotaPolicy,TenantApiUsageEvent,TenantApiWebhookDelivery,TenantApiWebhookEndpoint};use App\Domain\Network\Tenancy\Models\Tenant;use App\Models\User;use Illuminate\Database\Schema\Blueprint;use Illuminate\Support\Facades\{Crypt,DB,Http,Schema};use Tests\TestCase;
final class ZigoApiHubCommercialTest extends TestCase{private Tenant$tenant;private TenantApiClient$client;private string$plain;
 protected function setUp():void{parent::setUp();if(DB::connection()->getDriverName()!=='sqlite'||DB::connection()->getDatabaseName()!==':memory:')$this->markTestSkipped('Requires SQLite :memory:.');$this->schema();config(['zigo_api_hub.enabled'=>true,'zigo_api_hub.host'=>'api.zigo.local','zigo_api_hub.default_monthly_limit'=>10,'zigo_api_hub.default_rate_limit'=>60]);$user=User::create(['name'=>'Owner','email'=>'api@test','password'=>'x']);$this->tenant=Tenant::create(['name'=>'RapidGo','slug'=>'rapid-api','status'=>'active']);$plan=DB::table('network_plans')->insertGetId(['code'=>'API','name'=>'API','status'=>'active','currency'=>'MXN','created_at'=>now(),'updated_at'=>now()]);$sub=DB::table('network_subscriptions')->insertGetId(['uuid'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>$this->tenant->id,'plan_id'=>$plan,'status'=>'active','started_at'=>now()->subDay(),'current_period_start'=>now()->subDay(),'current_period_end'=>now()->addMonth(),'created_at'=>now(),'updated_at'=>now()]);DB::table('network_entitlements')->insert(['subscription_id'=>$sub,'tenant_id'=>$this->tenant->id,'code'=>'API','is_enabled'=>1,'source'=>'plan','created_at'=>now(),'updated_at'=>now()]);$this->client=TenantApiClient::create(['tenant_id'=>$this->tenant->id,'name'=>'SAP','environment'=>'STAGE','status'=>'ACTIVE','created_by_user_id'=>$user->id]);$this->plain='zg_stage_'.str_repeat('a',48);TenantApiKey::create(['tenant_id'=>$this->tenant->id,'api_client_id'=>$this->client->id,'key_prefix'=>'zg_stage','key_hash'=>hash('sha256',$this->plain),'last_four'=>'aaaa','name'=>'Main','scopes'=>TenantApiKey::SCOPES]);}
 public function test_legacy_postal_route_and_auth_contract_remain_unchanged():void{$routes=collect(app('router')->getRoutes()->getRoutes());$legacy=$routes->first(fn($r)=>$r->uri()==='api/hub/cp/{codigoPostal}');$this->assertNotNull($legacy);$this->assertContains('zigo.api',$legacy->gatherMiddleware());$this->assertStringContainsString('X-ZIGO-API-KEY',file_get_contents(app_path('Http/Middleware/ValidateZigoApiKey.php')));}
 public function test_v1_valid_bearer_is_host_bound_scoped_and_metered():void{DB::table('zigo_postal_codes')->insert(['codigo_postal'=>'64000','estado'=>'Nuevo León','municipio'=>'Monterrey','ciudad'=>'Monterrey','asentamiento'=>'Centro','tipo_asentamiento'=>'Colonia','zona'=>'Urbano','cobertura_estafeta'=>1,'activo'=>1,'created_at'=>now(),'updated_at'=>now()]);$response=$this->withHeader('Authorization','Bearer '.$this->plain)->getJson('http://api.zigo.local/api/hub/v1/postal-codes/64000')->assertOk()->assertJsonPath('data.postal_code','64000')->assertHeader('X-ZIGO-Quota-Limit','10');$this->assertNotNull($response->headers->get('X-ZIGO-Request-Id'));$this->assertSame(1,TenantApiUsageEvent::count());$this->withHeader('Authorization','Bearer '.$this->plain)->getJson('http://driver.zigo.local/api/hub/v1/postal-codes/64000')->assertNotFound();}
 public function test_invalid_revoked_and_insufficient_scope_do_not_meter():void{$this->getJson('http://api.zigo.local/api/hub/v1/postal-codes/64000')->assertStatus(401)->assertJsonPath('error.code','INVALID_API_KEY');$key=TenantApiKey::first();$key->update(['scopes'=>['quotes:write']]);$this->withHeader('Authorization','Bearer '.$this->plain)->getJson('http://api.zigo.local/api/hub/v1/postal-codes/64000')->assertStatus(403)->assertJsonPath('error.code','INSUFFICIENT_SCOPE');$key->update(['revoked_at'=>now()]);$this->withHeader('Authorization','Bearer '.$this->plain)->getJson('http://api.zigo.local/api/hub/v1/postal-codes/64000')->assertStatus(401);$this->assertSame(0,(int)TenantApiUsageEvent::sum('units'));}
 public function test_key_is_hash_only_and_never_serialized():void{$key=TenantApiKey::first();$this->assertNotSame($this->plain,$key->key_hash);$this->assertSame(hash('sha256',$this->plain),$key->key_hash);$this->assertArrayNotHasKey('key_hash',$key->toArray());}
 public function test_monthly_quota_is_ledger_derived_and_returns_429():void{TenantApiQuotaPolicy::create(['tenant_id'=>$this->tenant->id,'monthly_request_limit'=>1,'rate_limit_per_minute'=>60,'valid_from'=>now()->subMinute()]);DB::table('zigo_postal_codes')->insert(['codigo_postal'=>'64000','estado'=>'Nuevo León','municipio'=>'Monterrey','ciudad'=>'Monterrey','asentamiento'=>'Centro','tipo_asentamiento'=>'Colonia','zona'=>'Urbano','cobertura_estafeta'=>1,'activo'=>1,'created_at'=>now(),'updated_at'=>now()]);$this->withHeaders(['Authorization'=>'Bearer '.$this->plain,'X-ZIGO-Request-Id'=>'quota-request-01'])->getJson('http://api.zigo.local/api/hub/v1/postal-codes/64000')->assertOk();$this->withHeaders(['Authorization'=>'Bearer '.$this->plain,'X-ZIGO-Request-Id'=>'quota-request-02'])->getJson('http://api.zigo.local/api/hub/v1/postal-codes/64000')->assertStatus(429)->assertJsonPath('error.code','API_QUOTA_EXCEEDED')->assertHeader('X-ZIGO-Quota-Remaining','0');$this->assertSame(1,(int)TenantApiUsageEvent::sum('units'));}
 public function test_idempotency_replays_same_fingerprint_and_conflicts_on_change():void{$s=app(ApiIdempotencyService::class);$first=$s->execute($this->tenant->id,$this->client->id,'quotes.create','request-0001',['cp'=>'64000'],fn()=>['status'=>201,'body'=>['data'=>['quote_id'=>'opaque']]]);$same=$s->execute($this->tenant->id,$this->client->id,'quotes.create','request-0001',['cp'=>'64000'],fn()=>throw new \RuntimeException('must not run'));$conflict=$s->execute($this->tenant->id,$this->client->id,'quotes.create','request-0001',['cp'=>'01000'],fn()=>[]);$this->assertFalse($first['replay']);$this->assertTrue($same['replay']);$this->assertSame(409,$conflict['status']);$this->assertSame(1,TenantApiIdempotencyRecord::count());}
 public function test_webhook_signature_payload_and_secret_are_safe():void{Http::fake(['https://erp.example.test/*'=>Http::response('',204)]);$secret='zigo_whsec_safe';$endpoint=TenantApiWebhookEndpoint::create(['tenant_id'=>$this->tenant->id,'api_client_id'=>$this->client->id,'name'=>'ERP','url'=>'https://erp.example.test/events','events'=>['shipment.created'],'status'=>'ACTIVE','secret_encrypted'=>Crypt::encryptString($secret),'secret_prefix'=>'zigo_whsec']);$delivery=TenantApiWebhookDelivery::create(['event_id'=>(string)\Illuminate\Support\Str::uuid(),'tenant_id'=>$this->tenant->id,'api_client_id'=>$this->client->id,'webhook_endpoint_id'=>$endpoint->id,'event_type'=>'shipment.created','resource_type'=>'shipment','resource_uuid'=>(string)\Illuminate\Support\Str::uuid(),'payload'=>['event_id'=>'evt-safe','type'=>'shipment.created','data'=>['shipment_id'=>'ship-safe','tracking'=>'ZL1','status'=>'CREATED']],'status'=>'PENDING']);app(ApiWebhookDeliveryService::class)->deliver($delivery);$this->assertSame('DELIVERED',$delivery->fresh()->status);Http::assertSent(function($request)use($secret){$this->assertTrue($request->hasHeader('X-ZIGO-Signature'));$this->assertStringNotContainsString($secret,$request->body());foreach(['address','phone','signature','gps','earnings']as$private)$this->assertStringNotContainsString($private,strtolower($request->body()));return true;});$this->assertArrayNotHasKey('secret_encrypted',$endpoint->toArray());}
 public function test_openapi_and_migration_contract():void{$yaml=file_get_contents(base_path('docs/api-hub/openapi.yaml'));$this->assertSame(1,preg_match_all('/^components:\s*$/m',$yaml));foreach(['/quotes:','/shipments:','bearerApiKey','Idempotency-Key','x-zigo-scope']as$part)$this->assertStringContainsString($part,$yaml);$m=require database_path('migrations/2026_08_17_100000_create_tenant_api_hub_v1.php');$m->down();$this->assertFalse(Schema::hasTable('tenant_api_clients'));}
 private function schema():void{Schema::create('users',fn(Blueprint$t)=>$this->idTable($t,['name','email','password']));Schema::create('network_tenants',function(Blueprint$t){$t->id();$t->uuid('uuid')->nullable();$t->string('name');$t->string('slug');$t->string('status');$t->unsignedBigInteger('current_plan_id')->nullable();$t->timestamps();});Schema::create('network_plans',function(Blueprint$t){$t->id();$t->string('code');$t->string('name');$t->string('status');$t->string('currency');$t->timestamps();});Schema::create('network_subscriptions',function(Blueprint$t){$t->id();$t->uuid('uuid');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('plan_id');$t->string('status');$t->integer('operations_limit')->nullable();foreach(['started_at','current_period_start','current_period_end','trial_ends_at','grace_ends_at','canceled_at','ended_at']as$c)$t->timestamp($c)->nullable();$t->timestamps();});Schema::create('network_entitlements',function(Blueprint$t){$t->id();$t->unsignedBigInteger('subscription_id');$t->unsignedBigInteger('tenant_id');$t->unsignedBigInteger('module_id')->nullable();$t->string('code');$t->boolean('is_enabled');$t->integer('limit_value')->nullable();$t->string('source');$t->timestamps();});Schema::create('network_tenant_operations',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->timestamps();});Schema::create('local_shipments',function(Blueprint$t){$t->id();$t->uuid('uuid')->nullable();$t->unsignedBigInteger('tenant_id');$t->timestamps();});Schema::create('tenant_saas_orders',function(Blueprint$t){$t->id();$t->unsignedBigInteger('tenant_id');$t->timestamps();});Schema::create('zigo_postal_codes',function(Blueprint$t){$t->id();foreach(['codigo_postal','estado','municipio','ciudad','asentamiento','tipo_asentamiento','zona']as$c)$t->string($c)->nullable();$t->boolean('cobertura_estafeta');$t->boolean('activo');$t->timestamps();});$m=require database_path('migrations/2026_08_17_100000_create_tenant_api_hub_v1.php');$m->up();}
 private function idTable(Blueprint$t,array$columns):void{$t->id();foreach($columns as$c)$t->string($c);$t->timestamps();}
}

